module ComfyUI.Assets.CloudLoginViewXR4zaNTkJsMap

let file = """{"version":3,"file":"CloudLoginView-xR4zaNTk.js","names":[],"sources":["../../src/platform/cloud/onboarding/components/CloudSignInForm.vue","../../src/platform/cloud/onboarding/components/CloudSignInForm.vue","../../src/platform/cloud/onboarding/components/CloudSsoSignIn.vue","../../src/platform/cloud/onboarding/components/CloudSsoSignIn.vue","../../src/platform/cloud/onboarding/sso/ssoErrorMessages.ts","../../src/platform/cloud/onboarding/CloudLoginView.vue","../../src/platform/cloud/onboarding/CloudLoginView.vue"],"sourcesContent":["<template>\n  <form class=\"flex flex-col gap-6\" @submit.prevent=\"onSubmit\">\n    <VeeField v-slot=\"{ componentField, errors }\" name=\"email\">\n      <Field :data-invalid=\"!!errors.length\">\n        <FieldLabel :for=\"emailInputId\" :class=\"CLOUD_AUTH_LABEL_CLASS\">\n          {{ t('auth.login.emailLabel') }}\n        </FieldLabel>\n        <Input\n          v-bind=\"componentField\"\n          :id=\"emailInputId\"\n          autocomplete=\"email\"\n          :class=\"CLOUD_AUTH_FIELD_CLASS\"\n          type=\"text\"\n          :placeholder=\"t('auth.login.emailPlaceholder')\"\n          :aria-invalid=\"!!errors.length\"\n        />\n        <FieldError v-if=\"errors.length\" :errors />\n      </Field>\n    </VeeField>\n\n    <VeeField v-slot=\"{ componentField, errors }\" name=\"password\">\n      <Field :data-invalid=\"!!errors.length\">\n        <FieldLabel\n          for=\"cloud-sign-in-password\"\n          :class=\"CLOUD_AUTH_LABEL_CLASS\"\n        >\n          {{ t('auth.login.passwordLabel') }}\n        </FieldLabel>\n        <PasswordInput\n          v-bind=\"componentField\"\n          id=\"cloud-sign-in-password\"\n          autocomplete=\"current-password\"\n          :placeholder=\"t('auth.login.passwordPlaceholder')\"\n          :class=\"CLOUD_AUTH_FIELD_CLASS\"\n          :aria-invalid=\"!!errors.length\"\n        />\n        <FieldError v-if=\"errors.length\" :errors />\n\n        <router-link\n          :to=\"{ name: 'cloud-forgot-password' }\"\n          class=\"mt-1 self-start text-sm text-primary-comfy-canvas/70 underline\"\n        >\n          {{ t('auth.login.forgotPassword') }}\n        </router-link>\n      </Field>\n    </VeeField>\n\n    <Message v-if=\"authError\" severity=\"error\">\n      {{ authError }}\n    </Message>\n\n    <Button\n      type=\"submit\"\n      variant=\"brand-solid\"\n      size=\"brand\"\n      class=\"mt-2 w-full\"\n      :loading=\"loading || busy\"\n      :disabled=\"!meta.valid\"\n    >\n      {{ t('auth.login.loginButton') }}\n    </Button>\n  </form>\n</template>\n\n<script setup lang=\"ts\">\nimport { Field as VeeField, useForm } from 'vee-validate'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Field from '@/components/ui/field/Field.vue'\nimport FieldError from '@/components/ui/field/FieldError.vue'\nimport FieldLabel from '@/components/ui/field/FieldLabel.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport PasswordInput from '@/components/ui/input/PasswordInput.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport {\n  CLOUD_AUTH_FIELD_CLASS,\n  CLOUD_AUTH_LABEL_CLASS\n} from '@/platform/cloud/onboarding/constants/authClasses'\nimport { signInSchema } from '@/schemas/signInSchema'\nimport type { SignInData } from '@/schemas/signInSchema'\nimport { useAuthStore } from '@/stores/authStore'\nimport { toTypedSchema } from '@/utils/zodTypedSchema'\n\nconst authStore = useAuthStore()\nconst loading = computed(() => authStore.loading)\n\nconst { t } = useI18n()\n\nconst { busy = false } = defineProps<{\n  authError?: string\n  busy?: boolean\n}>()\n\nconst emit = defineEmits<{\n  submit: [values: SignInData]\n}>()\n\nconst emailInputId = 'cloud-sign-in-email'\n\nconst { handleSubmit, meta } = useForm({\n  validationSchema: toTypedSchema(signInSchema),\n  initialValues: { email: '', password: '' }\n})\n\nconst onSubmit = handleSubmit((values) => emit('submit', values))\n</script>\n","<template>\n  <form class=\"flex flex-col gap-6\" @submit.prevent=\"onSubmit\">\n    <VeeField v-slot=\"{ componentField, errors }\" name=\"email\">\n      <Field :data-invalid=\"!!errors.length\">\n        <FieldLabel :for=\"emailInputId\" :class=\"CLOUD_AUTH_LABEL_CLASS\">\n          {{ t('auth.login.emailLabel') }}\n        </FieldLabel>\n        <Input\n          v-bind=\"componentField\"\n          :id=\"emailInputId\"\n          autocomplete=\"email\"\n          :class=\"CLOUD_AUTH_FIELD_CLASS\"\n          type=\"text\"\n          :placeholder=\"t('auth.login.emailPlaceholder')\"\n          :aria-invalid=\"!!errors.length\"\n        />\n        <FieldError v-if=\"errors.length\" :errors />\n      </Field>\n    </VeeField>\n\n    <VeeField v-slot=\"{ componentField, errors }\" name=\"password\">\n      <Field :data-invalid=\"!!errors.length\">\n        <FieldLabel\n          for=\"cloud-sign-in-password\"\n          :class=\"CLOUD_AUTH_LABEL_CLASS\"\n        >\n          {{ t('auth.login.passwordLabel') }}\n        </FieldLabel>\n        <PasswordInput\n          v-bind=\"componentField\"\n          id=\"cloud-sign-in-password\"\n          autocomplete=\"current-password\"\n          :placeholder=\"t('auth.login.passwordPlaceholder')\"\n          :class=\"CLOUD_AUTH_FIELD_CLASS\"\n          :aria-invalid=\"!!errors.length\"\n        />\n        <FieldError v-if=\"errors.length\" :errors />\n\n        <router-link\n          :to=\"{ name: 'cloud-forgot-password' }\"\n          class=\"mt-1 self-start text-sm text-primary-comfy-canvas/70 underline\"\n        >\n          {{ t('auth.login.forgotPassword') }}\n        </router-link>\n      </Field>\n    </VeeField>\n\n    <Message v-if=\"authError\" severity=\"error\">\n      {{ authError }}\n    </Message>\n\n    <Button\n      type=\"submit\"\n      variant=\"brand-solid\"\n      size=\"brand\"\n      class=\"mt-2 w-full\"\n      :loading=\"loading || busy\"\n      :disabled=\"!meta.valid\"\n    >\n      {{ t('auth.login.loginButton') }}\n    </Button>\n  </form>\n</template>\n\n<script setup lang=\"ts\">\nimport { Field as VeeField, useForm } from 'vee-validate'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Field from '@/components/ui/field/Field.vue'\nimport FieldError from '@/components/ui/field/FieldError.vue'\nimport FieldLabel from '@/components/ui/field/FieldLabel.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport PasswordInput from '@/components/ui/input/PasswordInput.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport {\n  CLOUD_AUTH_FIELD_CLASS,\n  CLOUD_AUTH_LABEL_CLASS\n} from '@/platform/cloud/onboarding/constants/authClasses'\nimport { signInSchema } from '@/schemas/signInSchema'\nimport type { SignInData } from '@/schemas/signInSchema'\nimport { useAuthStore } from '@/stores/authStore'\nimport { toTypedSchema } from '@/utils/zodTypedSchema'\n\nconst authStore = useAuthStore()\nconst loading = computed(() => authStore.loading)\n\nconst { t } = useI18n()\n\nconst { busy = false } = defineProps<{\n  authError?: string\n  busy?: boolean\n}>()\n\nconst emit = defineEmits<{\n  submit: [values: SignInData]\n}>()\n\nconst emailInputId = 'cloud-sign-in-email'\n\nconst { handleSubmit, meta } = useForm({\n  validationSchema: toTypedSchema(signInSchema),\n  initialValues: { email: '', password: '' }\n})\n\nconst onSubmit = handleSubmit((values) => emit('submit', values))\n</script>\n","<template>\n  <form\n    class=\"flex flex-col gap-4\"\n    novalidate\n    @submit.prevent=\"emit('submit', email)\"\n  >\n    <label :for=\"emailInputId\" :class=\"CLOUD_AUTH_LABEL_CLASS\">\n      {{ t('auth.sso.emailLabel') }}\n    </label>\n    <Input\n      :id=\"emailInputId\"\n      v-model=\"email\"\n      type=\"email\"\n      autocomplete=\"email\"\n      :placeholder=\"t('auth.sso.emailPlaceholder')\"\n      :class=\"CLOUD_AUTH_FIELD_CLASS\"\n    />\n\n    <Message v-if=\"feedback\" :severity=\"feedback.severity\">\n      {{ t(feedback.key) }}\n    </Message>\n\n    <Button\n      type=\"submit\"\n      variant=\"brand-solid\"\n      size=\"brand\"\n      class=\"w-full\"\n      :loading=\"busy\"\n      :disabled=\"!email.trim()\"\n    >\n      {{ t('auth.sso.submit') }}\n    </Button>\n  </form>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport { readSsoHint } from '@/platform/auth/session/ssoReentryStorage'\nimport {\n  CLOUD_AUTH_FIELD_CLASS,\n  CLOUD_AUTH_LABEL_CLASS\n} from '@/platform/cloud/onboarding/constants/authClasses'\nimport type { SsoSignInState } from '@/platform/cloud/onboarding/sso/ssoSignInState'\nimport { isSsoBusy } from '@/platform/cloud/onboarding/sso/ssoSignInState'\n\nconst FEEDBACK: Partial<\n  Record<SsoSignInState['phase'], { key: string; severity: 'info' | 'error' }>\n> = {\n  'not-sso': { key: 'auth.sso.notSso', severity: 'info' },\n  'invalid-email': { key: 'auth.sso.invalidEmail', severity: 'error' },\n  unavailable: { key: 'auth.sso.unavailable', severity: 'error' }\n}\n\nconst { state } = defineProps<{ state: SsoSignInState }>()\nconst emit = defineEmits<{ submit: [email: string] }>()\n\nconst { t } = useI18n()\nconst busy = computed(() => isSsoBusy(state))\n\nconst emailInputId = 'cloud-sso-email'\nconst email = ref(readSsoHint()?.email ?? '')\nconst feedback = computed(() => FEEDBACK[state.phase])\n</script>\n","<template>\n  <form\n    class=\"flex flex-col gap-4\"\n    novalidate\n    @submit.prevent=\"emit('submit', email)\"\n  >\n    <label :for=\"emailInputId\" :class=\"CLOUD_AUTH_LABEL_CLASS\">\n      {{ t('auth.sso.emailLabel') }}\n    </label>\n    <Input\n      :id=\"emailInputId\"\n      v-model=\"email\"\n      type=\"email\"\n      autocomplete=\"email\"\n      :placeholder=\"t('auth.sso.emailPlaceholder')\"\n      :class=\"CLOUD_AUTH_FIELD_CLASS\"\n    />\n\n    <Message v-if=\"feedback\" :severity=\"feedback.severity\">\n      {{ t(feedback.key) }}\n    </Message>\n\n    <Button\n      type=\"submit\"\n      variant=\"brand-solid\"\n      size=\"brand\"\n      class=\"w-full\"\n      :loading=\"busy\"\n      :disabled=\"!email.trim()\"\n    >\n      {{ t('auth.sso.submit') }}\n    </Button>\n  </form>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport { readSsoHint } from '@/platform/auth/session/ssoReentryStorage'\nimport {\n  CLOUD_AUTH_FIELD_CLASS,\n  CLOUD_AUTH_LABEL_CLASS\n} from '@/platform/cloud/onboarding/constants/authClasses'\nimport type { SsoSignInState } from '@/platform/cloud/onboarding/sso/ssoSignInState'\nimport { isSsoBusy } from '@/platform/cloud/onboarding/sso/ssoSignInState'\n\nconst FEEDBACK: Partial<\n  Record<SsoSignInState['phase'], { key: string; severity: 'info' | 'error' }>\n> = {\n  'not-sso': { key: 'auth.sso.notSso', severity: 'info' },\n  'invalid-email': { key: 'auth.sso.invalidEmail', severity: 'error' },\n  unavailable: { key: 'auth.sso.unavailable', severity: 'error' }\n}\n\nconst { state } = defineProps<{ state: SsoSignInState }>()\nconst emit = defineEmits<{ submit: [email: string] }>()\n\nconst { t } = useI18n()\nconst busy = computed(() => isSsoBusy(state))\n\nconst emailInputId = 'cloud-sso-email'\nconst email = ref(readSsoHint()?.email ?? '')\nconst feedback = computed(() => FEEDBACK[state.phase])\n</script>\n","import type { SsoErrorCode } from '@comfyorg/account-core/sso'\n\nexport const SSO_ERROR_MESSAGE_KEY: Readonly<Record<SsoErrorCode, string>> = {\n  SSO_UNAVAILABLE: 'auth.sso.errors.unavailable',\n  SSO_LINK_CHECK_FAILED: 'auth.sso.errors.unavailable',\n  SSO_CONFIRM_EXPIRED: 'auth.sso.errors.expired',\n  SSO_EMAIL_DOMAIN_NOT_ALLOWED: 'auth.sso.errors.emailDomainNotAllowed',\n  SSO_INVALID_STATE: 'auth.sso.errors.expired',\n  SSO_NOT_CONFIGURED: 'auth.sso.errors.notConfigured',\n  SSO_ORG_DISABLED: 'auth.sso.errors.orgDisabled',\n  SSO_ORG_NOT_ATTACHED: 'auth.sso.errors.orgNotAttached',\n  SSO_ORG_MISMATCH: 'auth.sso.errors.orgMismatch',\n  SSO_USER_SUSPENDED: 'auth.sso.errors.suspended',\n  SSO_ACCOUNT_DELETED: 'auth.sso.errors.accountDeleted',\n  SSO_ACCOUNT_CONFLICT: 'auth.sso.errors.accountConflict',\n  SSO_IDP_ERROR: 'auth.sso.errors.idpError',\n  RATE_LIMITED: 'auth.sso.errors.rateLimited',\n  SSO_EXCHANGE_FAILED: 'auth.sso.errors.failed',\n  SSO_SIGN_IN_FAILED: 'auth.sso.errors.failed',\n  SESSION_CREATION_FAILED: 'auth.sso.errors.failed',\n  INTERNAL_ERROR: 'auth.sso.errors.failed'\n}\n","<template>\n  <div class=\"flex w-full flex-col\">\n    <h1\n      class=\"mt-8 mb-0 text-2xl/snug font-light tracking-tighter text-primary-comfy-canvas sm:text-3xl/snug lg:text-4xl/snug xl:text-5xl/snug 2xl:text-6xl/snug\"\n    >\n      {{ t('auth.login.title') }}\n    </h1>\n\n    <p\n      class=\"mt-8 mb-0 text-base/snug font-medium text-primary-comfy-canvas xl:text-lg/snug\"\n    >\n      {{ t('auth.login.cloudNewUser') }}\n      <RouterLink\n        :to=\"{ name: 'cloud-signup', query: route.query }\"\n        class=\"text-brand-yellow no-underline transition-all duration-300 hover:underline\"\n      >\n        {{ t('auth.login.cloudSignUp') }}\n      </RouterLink>\n      <span v-if=\"freeRunsSuffix\">{{ ' ' + freeRunsSuffix }}</span>\n    </p>\n\n    <Message v-if=\"!isSecureContext\" severity=\"warning\" class=\"mt-4 w-full\">\n      {{ t('auth.login.insecureContextWarning') }}\n    </Message>\n\n    <Message v-if=\"ssoErrorKey\" severity=\"error\" class=\"mt-4 w-full\">\n      {{ t(ssoErrorKey) }}\n    </Message>\n\n    <CloudSsoRequiredNotice\n      v-if=\"ssoRequiredNotice\"\n      v-bind=\"ssoRequiredNotice\"\n      class=\"mt-4\"\n    />\n\n    <div class=\"mt-12 flex flex-col gap-4 xl:gap-6\">\n      <template v-if=\"authMode !== 'email'\">\n        <CloudSocialAuthButtons\n          :google-label=\"t('auth.login.loginWithGoogle')\"\n          :github-label=\"t('auth.login.loginWithGithub')\"\n          :show-in-app-browser-notice=\"showGoogleSsoInAppBrowserNotice\"\n          @google=\"signInWithGoogle\"\n          @github=\"signInWithGithub\"\n        />\n\n        <template v-if=\"flags.ssoEnabled && !ssoRequiredNotice\">\n          <CloudSsoSignIn\n            v-if=\"authMode === 'sso'\"\n            :state=\"ssoState\"\n            @submit=\"trySso\"\n          />\n          <Button\n            v-else\n            type=\"button\"\n            variant=\"brand-ghost\"\n            size=\"brand\"\n            class=\"w-full gap-3\"\n            @click=\"switchToSsoForm\"\n          >\n            <i class=\"icon-[lucide--building-2] size-5\" aria-hidden=\"true\" />\n            {{ t('auth.sso.continueWithSso') }}\n          </Button>\n        </template>\n\n        <button\n          type=\"button\"\n          :class=\"CLOUD_AUTH_LINK_BUTTON_CLASS\"\n          @click=\"switchToEmailForm\"\n        >\n          {{ t('auth.login.useEmailInstead') }}\n        </button>\n      </template>\n\n      <template v-else>\n        <CloudSignInForm\n          :auth-error=\"authError\"\n          :busy=\"ssoBusy\"\n          @submit=\"signInWithEmail\"\n        />\n\n        <button\n          type=\"button\"\n          :class=\"CLOUD_AUTH_LINK_BUTTON_CLASS\"\n          @click=\"switchToSocialLogin\"\n        >\n          {{ t('auth.login.backToSocialLogin') }}\n        </button>\n      </template>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { omit } from 'es-toolkit'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { RouterLink, useRoute, useRouter } from 'vue-router'\n\nimport { readSsoError } from '@comfyorg/account-core/sso'\nimport { ssoFailureReason } from '@comfyorg/account-core/telemetry'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport { useAuthActions } from '@/composables/auth/useAuthActions'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { trackSsoSignInFailed } from '@/platform/auth/sso/ssoTelemetry'\nimport CloudSignInForm from '@/platform/cloud/onboarding/components/CloudSignInForm.vue'\nimport CloudSocialAuthButtons from '@/platform/cloud/onboarding/components/CloudSocialAuthButtons.vue'\nimport CloudSsoRequiredNotice from '@/platform/cloud/onboarding/components/CloudSsoRequiredNotice.vue'\nimport CloudSsoSignIn from '@/platform/cloud/onboarding/components/CloudSsoSignIn.vue'\nimport { useCloudAuthPage } from '@/platform/cloud/onboarding/composables/useCloudAuthPage'\nimport { useSsoSignIn } from '@/platform/cloud/onboarding/composables/useSsoSignIn'\nimport { CLOUD_AUTH_LINK_BUTTON_CLASS } from '@/platform/cloud/onboarding/constants/authClasses'\nimport { SSO_ERROR_MESSAGE_KEY } from '@/platform/cloud/onboarding/sso/ssoErrorMessages'\nimport { remoteConfig } from '@/platform/remoteConfig/remoteConfig'\nimport type { SignInData } from '@/schemas/signInSchema'\n\nconst { t } = useI18n()\nconst route = useRoute()\nconst router = useRouter()\nconst authActions = useAuthActions()\nconst { flags } = useFeatureFlags()\nconst { state: ssoState, busy: ssoBusy, trySso } = useSsoSignIn('cloud_login')\n\nconst freeRunsSuffix = computed(() => {\n  const offer = remoteConfig.value.free_tier_offer\n  if (!offer) return null\n  const key = offer.requires_google_sign_in\n    ? 'auth.login.freeRunsSuffixGoogle'\n    : 'auth.login.freeRunsSuffix'\n  return t(key, { count: offer.job_allowance })\n})\n\nconst {\n  authError,\n  authMode,\n  ssoRequiredNotice,\n  onAuthSuccess,\n  isSecureContext,\n  showGoogleSsoInAppBrowserNotice,\n  switchToEmailForm,\n  switchToSsoForm,\n  switchToSocialLogin,\n  signInWithGoogle,\n  signInWithGithub\n} = useCloudAuthPage({\n  successSummary: 'Login Completed',\n  defaultRedirect: () => ({ name: 'cloud-user-check' })\n})\n\nconst ssoError = readSsoError(route.query.sso_error)\nconst ssoErrorKey = computed(\n  () => flags.ssoEnabled && ssoError && SSO_ERROR_MESSAGE_KEY[ssoError]\n)\n\nif (flags.ssoEnabled && ssoError) {\n  trackSsoSignInFailed(ssoFailureReason(ssoError), 'cloud_login')\n  void router.replace({ query: omit(route.query, ['sso_error']) })\n}\n\nconst signInWithEmail = async (values: SignInData) => {\n  authError.value = ''\n  if (flags.ssoEnabled && (await trySso(values.email))) return\n  if (await authActions.signInWithEmail(values.email, values.password)) {\n    await onAuthSuccess()\n  }\n}\n</script>\n","<template>\n  <div class=\"flex w-full flex-col\">\n    <h1\n      class=\"mt-8 mb-0 text-2xl/snug font-light tracking-tighter text-primary-comfy-canvas sm:text-3xl/snug lg:text-4xl/snug xl:text-5xl/snug 2xl:text-6xl/snug\"\n    >\n      {{ t('auth.login.title') }}\n    </h1>\n\n    <p\n      class=\"mt-8 mb-0 text-base/snug font-medium text-primary-comfy-canvas xl:text-lg/snug\"\n    >\n      {{ t('auth.login.cloudNewUser') }}\n      <RouterLink\n        :to=\"{ name: 'cloud-signup', query: route.query }\"\n        class=\"text-brand-yellow no-underline transition-all duration-300 hover:underline\"\n      >\n        {{ t('auth.login.cloudSignUp') }}\n      </RouterLink>\n      <span v-if=\"freeRunsSuffix\">{{ ' ' + freeRunsSuffix }}</span>\n    </p>\n\n    <Message v-if=\"!isSecureContext\" severity=\"warning\" class=\"mt-4 w-full\">\n      {{ t('auth.login.insecureContextWarning') }}\n    </Message>\n\n    <Message v-if=\"ssoErrorKey\" severity=\"error\" class=\"mt-4 w-full\">\n      {{ t(ssoErrorKey) }}\n    </Message>\n\n    <CloudSsoRequiredNotice\n      v-if=\"ssoRequiredNotice\"\n      v-bind=\"ssoRequiredNotice\"\n      class=\"mt-4\"\n    />\n\n    <div class=\"mt-12 flex flex-col gap-4 xl:gap-6\">\n      <template v-if=\"authMode !== 'email'\">\n        <CloudSocialAuthButtons\n          :google-label=\"t('auth.login.loginWithGoogle')\"\n          :github-label=\"t('auth.login.loginWithGithub')\"\n          :show-in-app-browser-notice=\"showGoogleSsoInAppBrowserNotice\"\n          @google=\"signInWithGoogle\"\n          @github=\"signInWithGithub\"\n        />\n\n        <template v-if=\"flags.ssoEnabled && !ssoRequiredNotice\">\n          <CloudSsoSignIn\n            v-if=\"authMode === 'sso'\"\n            :state=\"ssoState\"\n            @submit=\"trySso\"\n          />\n          <Button\n            v-else\n            type=\"button\"\n            variant=\"brand-ghost\"\n            size=\"brand\"\n            class=\"w-full gap-3\"\n            @click=\"switchToSsoForm\"\n          >\n            <i class=\"icon-[lucide--building-2] size-5\" aria-hidden=\"true\" />\n            {{ t('auth.sso.continueWithSso') }}\n          </Button>\n        </template>\n\n        <button\n          type=\"button\"\n          :class=\"CLOUD_AUTH_LINK_BUTTON_CLASS\"\n          @click=\"switchToEmailForm\"\n        >\n          {{ t('auth.login.useEmailInstead') }}\n        </button>\n      </template>\n\n      <template v-else>\n        <CloudSignInForm\n          :auth-error=\"authError\"\n          :busy=\"ssoBusy\"\n          @submit=\"signInWithEmail\"\n        />\n\n        <button\n          type=\"button\"\n          :class=\"CLOUD_AUTH_LINK_BUTTON_CLASS\"\n          @click=\"switchToSocialLogin\"\n        >\n          {{ t('auth.login.backToSocialLogin') }}\n        </button>\n      </template>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { omit } from 'es-toolkit'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { RouterLink, useRoute, useRouter } from 'vue-router'\n